patch_result.patch:
--- a/src/ports/SkFontHost_FreeType.cpp
+++ b/src/ports/SkFontHost_FreeType.cpp
@@ -1556,7 +1556,17 @@
 int SkTypeface_FreeType::onCountGlyphs() const {
     AutoFTAccess fta(this);
     FT_Face face = fta.face();
-    return face ? face->num_glyphs : 0;
+    if (!face) {
+        return 0;
+    }
+
+    // Defensive validation for malformed fonts: FreeType face metadata may be
+    // invalid or uninitialized for fuzzed/broken inputs. Keep behavior for
+    // valid fonts while ensuring we never propagate a negative/tainted count.
+    if (face->num_glyphs <= 0) {
+        return 0;
+    }
+    return SkToInt(face->num_glyphs);
 }

